<?php namespace App\Services; use App\Models\{Appointment,Vet}; use Illuminate\Validation\ValidationException; use Carbon\Carbon; class AppointmentService { public function ensureAvailable(Vet $vet,Carbon $start,Carbon $end,?int $ignoreId=null):void { if(!$start->lt($end)) throw ValidationException::withMessages(['starts_at'=>'Start time must be before end time.']); $q=Appointment::where('vet_id',$vet->id)->whereIn('status',['pending','confirmed'])->where(function($q)use($start,$end){$q->where('starts_at','<',$end)->where('ends_at','>',$start);}); if($ignoreId)$q->where('id','<>',$ignoreId); if($q->exists()) throw ValidationException::withMessages(['starts_at'=>'The veterinarian already has an overlapping appointment.']); } }